// src/pages/listening/ClipPlayer.tsx
//
// /listening/:clipId — single-clip player + transcript + comprehension
// quiz. Auth-required (the parent route gates on AuthProvider).
//
// audio_url is generated by a separate background job; until it is
// populated, this page renders a "Audio đang được chuẩn bị" notice
// and shows the transcript directly. Once audio URLs land in the
// listening_clips table, the player below will pick them up via the
// optional `audioUrl` prop.
//
// Replays are counted client-side as the number of times the user
// presses Play after the first start. The count is sent with the
// progress UPSERT on quiz submission.

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Link, Navigate, useParams } from "react-router-dom";
import { ChevronLeft, Eye, EyeOff, Pause, Play, RotateCcw } from "lucide-react";

import { useAuth } from "@/providers/AuthProvider";
import {
  getListeningClipById,
  suggestNextInCategory,
  type ListeningClip,
  type ListeningCategory,
} from "@/data/listening/clips";
import {
  getCompletedClipIds,
  saveListeningProgress,
} from "@/services/listeningProgress";

const wrap: React.CSSProperties = {
  width: "100%",
  minHeight: "calc(100vh - 72px)",
  padding: "20px 16px 80px",
  display: "flex",
  justifyContent: "center",
};
const column: React.CSSProperties = {
  width: "100%",
  maxWidth: 720,
  display: "flex",
  flexDirection: "column",
  gap: 16,
};
const cardStyle: React.CSSProperties = {
  border: "1px solid rgba(0,0,0,0.10)",
  borderRadius: 16,
  padding: 18,
  background: "white",
  boxShadow: "0 6px 18px rgba(0,0,0,0.04)",
};
const sectionTitle: React.CSSProperties = {
  fontSize: 12,
  fontWeight: 700,
  textTransform: "uppercase",
  letterSpacing: 0.4,
  color: "rgba(0,0,0,0.55)",
};

const PLAYBACK_RATES = [0.75, 1, 1.25] as const;
type PlaybackRate = (typeof PLAYBACK_RATES)[number];

function highlightVocab(text: string, keys: ReadonlyArray<string>): React.ReactNode {
  if (keys.length === 0) return text;
  // Build a single case-insensitive regex across all keys, escaping
  // regex metacharacters in the keys themselves.
  const escaped = keys.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const pattern = new RegExp(`(${escaped.join("|")})`, "gi");
  const parts = text.split(pattern);
  return parts.map((part, i) => {
    if (i % 2 === 1) {
      return (
        <mark
          key={i}
          style={{
            background: "#fef3c7",
            padding: "0 2px",
            borderRadius: 3,
            fontWeight: 700,
          }}
        >
          {part}
        </mark>
      );
    }
    return <React.Fragment key={i}>{part}</React.Fragment>;
  });
}

export default function ClipPlayer(): React.ReactElement {
  const { clipId = "" } = useParams<{ clipId: string }>();
  const { user, isLoading: authLoading } = useAuth();
  const clip = getListeningClipById(clipId);

  // Player state — used only when audio_url lands. For now we expose
  // the controls but disable Play until an audio source is available.
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [rate, setRate] = useState<PlaybackRate>(1);
  const [replays, setReplays] = useState(0);
  const [hasStarted, setHasStarted] = useState(false);

  const [showTranscript, setShowTranscript] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [answers, setAnswers] = useState<Array<number | null>>([null, null]);
  const [submitted, setSubmitted] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [nextClip, setNextClip] = useState<ListeningClip | null>(null);

  // Once submitted, find the suggested next clip in the same category.
  useEffect(() => {
    if (!submitted || !clip) return;
    let alive = true;
    void getCompletedClipIds().then((ids) => {
      if (!alive) return;
      const next = suggestNextInCategory(clip.category, ids);
      if (next && next.id !== clip.id) setNextClip(next);
    });
    return () => {
      alive = false;
    };
  }, [submitted, clip]);

  const score = useMemo(() => {
    if (!clip) return 0;
    return clip.comprehension_questions.reduce((acc, q, i) => {
      return answers[i] === q.correct_index ? acc + 1 : acc;
    }, 0);
  }, [clip, answers]);

  const handlePlay = useCallback(() => {
    if (!audioRef.current) return;
    audioRef.current.playbackRate = rate;
    if (hasStarted) {
      // A user pressing Play after the first run counts as a replay.
      setReplays((r) => r + 1);
    } else {
      setHasStarted(true);
    }
    void audioRef.current.play();
    setIsPlaying(true);
  }, [rate, hasStarted]);

  const handlePause = useCallback(() => {
    audioRef.current?.pause();
    setIsPlaying(false);
  }, []);

  const handleReplay = useCallback(() => {
    if (!audioRef.current) return;
    audioRef.current.currentTime = 0;
    audioRef.current.playbackRate = rate;
    setReplays((r) => r + 1);
    void audioRef.current.play();
    setIsPlaying(true);
  }, [rate]);

  const handleSubmit = useCallback(async () => {
    if (!clip) return;
    setSubmitted(true);
    const result = await saveListeningProgress({
      clipId: clip.id,
      score,
      totalQuestions: clip.comprehension_questions.length,
      replays,
    });
    if (!result.ok) setSaveError(result.error ?? "save_failed");
  }, [clip, score, replays]);

  const handleReset = useCallback(() => {
    setAnswers([null, null]);
    setSubmitted(false);
    setSaveError(null);
  }, []);

  if (authLoading) {
    return (
      <div style={wrap}>
        <p style={{ color: "#64748b", fontSize: 13 }}>Đang tải… · Loading…</p>
      </div>
    );
  }
  if (!user) return <Navigate to="/signin" replace />;

  if (!clip) {
    return (
      <div style={wrap}>
        <div style={column}>
          <p style={{ color: "#64748b", fontSize: 13 }}>
            Không tìm thấy đoạn nghe · Clip not found.
          </p>
          <Link to="/listening" style={{ color: "#1e3a8a", fontWeight: 700 }}>
            ← Quay lại thư viện · Back to library
          </Link>
        </div>
      </div>
    );
  }

  const categoryLabel: Record<ListeningCategory, string> = {
    restaurant:         "Nhà hàng",
    doctor:             "Bác sĩ",
    "customer-service": "CSKH",
    "job-interview":    "Phỏng vấn",
    casual:             "Đời thường",
    shopping:           "Mua sắm",
    transportation:     "Di chuyển",
  };

  return (
    <div style={wrap}>
      <div style={column}>
        <Link
          to="/listening"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 4,
            color: "#475569",
            fontSize: 13,
            textDecoration: "none",
          }}
          aria-label="Back to library"
        >
          <ChevronLeft size={14} aria-hidden />
          Thư viện · Library
        </Link>

        {/* Hero */}
        <header style={cardStyle}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#64748b", textTransform: "uppercase" }}>
            {categoryLabel[clip.category]} · {clip.duration_seconds}s · {clip.accent.toUpperCase()}
          </div>
          <h1 style={{ fontSize: 22, fontWeight: 950, margin: "6px 0 2px", color: "rgba(10,10,10,0.94)" }}>
            {clip.title_vi}
          </h1>
          <div style={{ fontSize: 13, color: "#94a3b8" }}>{clip.title_en}</div>
          <p style={{ fontSize: 13, color: "#475569", marginTop: 10, lineHeight: 1.55 }}>
            {clip.description_vi}
          </p>
        </header>

        {/* Audio (or pending notice) */}
        <section style={cardStyle} aria-label="Audio player">
          <div style={sectionTitle}>Audio</div>
          {/* Audio URL is intentionally absent in the seed pack — TTS
              backfill populates it later. We render the controls but
              keep them disabled until the source exists. */}
          <audio
            ref={audioRef}
            preload="none"
            onEnded={() => setIsPlaying(false)}
            data-testid="listening-audio"
          />
          <p
            style={{
              fontSize: 12,
              background: "#fffbeb",
              border: "1px solid #fde68a",
              borderRadius: 8,
              padding: "8px 10px",
              color: "#78350f",
              margin: "8px 0",
            }}
            data-testid="listening-audio-pending"
          >
            🎧 Audio đang được chuẩn bị · Audio is being prepared. Đọc kịch bản
            bên dưới trong khi chờ.
          </p>

          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            <button
              type="button"
              onClick={isPlaying ? handlePause : handlePlay}
              disabled
              data-testid="listening-play-pause"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                padding: "8px 14px",
                borderRadius: 9999,
                border: "1px solid rgba(0,0,0,0.12)",
                background: "#1e3a8a",
                color: "white",
                fontSize: 13,
                fontWeight: 700,
                cursor: "not-allowed",
                opacity: 0.6,
              }}
            >
              {isPlaying ? <Pause size={14} aria-hidden /> : <Play size={14} aria-hidden />}
              {isPlaying ? "Tạm dừng" : "Phát"}
            </button>
            <button
              type="button"
              onClick={handleReplay}
              disabled
              data-testid="listening-replay"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                padding: "8px 14px",
                borderRadius: 9999,
                border: "1px solid rgba(0,0,0,0.12)",
                background: "white",
                color: "#1f2937",
                fontSize: 13,
                fontWeight: 700,
                cursor: "not-allowed",
                opacity: 0.6,
              }}
            >
              <RotateCcw size={14} aria-hidden />
              Phát lại
            </button>
            <div style={{ display: "flex", gap: 4 }}>
              {PLAYBACK_RATES.map((r) => (
                <button
                  key={r}
                  type="button"
                  onClick={() => setRate(r)}
                  data-testid={`listening-rate-${r}`}
                  style={{
                    padding: "4px 10px",
                    borderRadius: 9999,
                    fontSize: 11,
                    fontWeight: 700,
                    border: `1px solid ${rate === r ? "#1e3a8a" : "rgba(0,0,0,0.12)"}`,
                    background: rate === r ? "#1e3a8a" : "white",
                    color: rate === r ? "white" : "#1f2937",
                    cursor: "pointer",
                  }}
                >
                  {r}x
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* Transcript toggle */}
        <section style={cardStyle} aria-label="Transcript">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={sectionTitle}>Transcript · Kịch bản</div>
            <button
              type="button"
              onClick={() => setShowTranscript((v) => !v)}
              data-testid="listening-toggle-transcript"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                padding: "4px 10px",
                borderRadius: 9999,
                border: "1px solid rgba(0,0,0,0.12)",
                background: "white",
                fontSize: 11,
                fontWeight: 700,
                cursor: "pointer",
              }}
            >
              {showTranscript ? <EyeOff size={12} aria-hidden /> : <Eye size={12} aria-hidden />}
              {showTranscript ? "Ẩn" : "Hiện"}
            </button>
          </div>
          {showTranscript ? (
            <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 12 }}>
              {clip.transcript.map((turn, i) => (
                <div key={i}>
                  <div style={{ fontSize: 11, fontWeight: 800, color: "#64748b" }}>
                    {turn.speaker}
                  </div>
                  <div style={{ fontSize: 14, color: "#1f2937", lineHeight: 1.55, marginTop: 2 }}>
                    {highlightVocab(turn.text_en, clip.vocabulary_keys)}
                  </div>
                  <div style={{ fontSize: 12, color: "#64748b", marginTop: 2, fontStyle: "italic" }}>
                    {turn.text_vi}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p style={{ fontSize: 12, color: "#94a3b8", marginTop: 8 }}>
              Nghe trước khi đọc — bấm 'Hiện' khi muốn xem.
            </p>
          )}
        </section>

        {/* Quiz */}
        {!showQuiz ? (
          <button
            type="button"
            onClick={() => setShowQuiz(true)}
            data-testid="listening-start-quiz"
            style={{
              alignSelf: "flex-start",
              padding: "10px 18px",
              borderRadius: 9999,
              background: "#059669",
              color: "white",
              fontSize: 14,
              fontWeight: 700,
              border: "none",
              cursor: "pointer",
            }}
          >
            Trả lời câu hỏi · Answer questions
          </button>
        ) : (
          <section style={cardStyle} aria-label="Comprehension quiz">
            <div style={sectionTitle}>Câu hỏi · Questions</div>
            <ol
              style={{
                margin: "12px 0 0",
                paddingLeft: 18,
                display: "flex",
                flexDirection: "column",
                gap: 16,
              }}
            >
              {clip.comprehension_questions.map((q, qi) => {
                const userAnswer = answers[qi];
                const isCorrect = submitted && userAnswer === q.correct_index;
                return (
                  <li key={qi}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: "#1f2937" }}>
                      {q.question_vi}
                    </div>
                    <ul style={{ listStyle: "none", padding: 0, margin: "8px 0 0", display: "flex", flexDirection: "column", gap: 6 }}>
                      {q.options.map((opt, oi) => {
                        const selected = userAnswer === oi;
                        let bg = "white";
                        let border = "rgba(0,0,0,0.12)";
                        if (submitted) {
                          if (oi === q.correct_index) {
                            bg = "#ecfdf5";
                            border = "#a7f3d0";
                          } else if (selected) {
                            bg = "#fef2f2";
                            border = "#fecaca";
                          }
                        } else if (selected) {
                          bg = "#eff6ff";
                          border = "#93c5fd";
                        }
                        return (
                          <li key={oi}>
                            <button
                              type="button"
                              onClick={() =>
                                setAnswers((prev) => {
                                  if (submitted) return prev;
                                  const next = [...prev];
                                  next[qi] = oi;
                                  return next;
                                })
                              }
                              disabled={submitted}
                              data-testid={`listening-quiz-${qi}-option-${oi}`}
                              style={{
                                width: "100%",
                                textAlign: "left",
                                padding: "8px 12px",
                                background: bg,
                                border: `1px solid ${border}`,
                                borderRadius: 10,
                                fontSize: 13,
                                color: "#1f2937",
                                cursor: submitted ? "default" : "pointer",
                              }}
                            >
                              {opt}
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                    {submitted ? (
                      <p
                        style={{
                          fontSize: 12,
                          color: isCorrect ? "#065f46" : "#991b1b",
                          marginTop: 6,
                        }}
                      >
                        {isCorrect ? "✓ Đúng — " : "✗ Sai — "}
                        {q.explanation_vi}
                      </p>
                    ) : null}
                  </li>
                );
              })}
            </ol>

            {!submitted ? (
              <button
                type="button"
                onClick={() => void handleSubmit()}
                disabled={answers.some((a) => a === null)}
                data-testid="listening-submit-quiz"
                style={{
                  marginTop: 16,
                  padding: "10px 18px",
                  borderRadius: 9999,
                  background: "#059669",
                  color: "white",
                  fontSize: 14,
                  fontWeight: 700,
                  border: "none",
                  cursor: answers.some((a) => a === null) ? "not-allowed" : "pointer",
                  opacity: answers.some((a) => a === null) ? 0.6 : 1,
                }}
              >
                Nộp · Submit
              </button>
            ) : (
              <div
                style={{
                  marginTop: 16,
                  padding: 12,
                  background: "#ecfdf5",
                  border: "1px solid #a7f3d0",
                  borderRadius: 10,
                }}
              >
                <div style={{ fontSize: 14, fontWeight: 800, color: "#065f46" }}>
                  Kết quả: {score} / {clip.comprehension_questions.length}
                </div>
                {saveError ? (
                  <div style={{ fontSize: 11, color: "#991b1b", marginTop: 4 }}>
                    Không lưu được tiến độ: {saveError}
                  </div>
                ) : (
                  <div style={{ fontSize: 11, color: "#065f46", marginTop: 4 }}>
                    Đã lưu vào Tiến độ nghe của bạn.
                  </div>
                )}
                <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
                  <button
                    type="button"
                    onClick={handleReset}
                    style={{
                      padding: "6px 12px",
                      borderRadius: 9999,
                      border: "1px solid rgba(0,0,0,0.12)",
                      background: "white",
                      fontSize: 12,
                      fontWeight: 700,
                      cursor: "pointer",
                    }}
                  >
                    Làm lại · Try again
                  </button>
                  {nextClip ? (
                    <Link
                      to={`/listening/${nextClip.id}`}
                      data-testid="listening-next-clip"
                      style={{
                        padding: "6px 12px",
                        borderRadius: 9999,
                        background: "#1e3a8a",
                        color: "white",
                        fontSize: 12,
                        fontWeight: 700,
                        textDecoration: "none",
                      }}
                    >
                      Bài tiếp theo: {nextClip.title_vi} →
                    </Link>
                  ) : (
                    <Link
                      to="/listening"
                      style={{
                        padding: "6px 12px",
                        borderRadius: 9999,
                        background: "white",
                        color: "#1f2937",
                        fontSize: 12,
                        fontWeight: 700,
                        textDecoration: "none",
                        border: "1px solid rgba(0,0,0,0.12)",
                      }}
                    >
                      Hoàn thành — về thư viện
                    </Link>
                  )}
                </div>
              </div>
            )}
          </section>
        )}
      </div>
    </div>
  );
}
